import Foundation
#if canImport(FoundationNetworking)
import FoundationNetworking
#endif
import Testing
@testable import InfluxKit

/// The Sammy server's contract files (Fixtures/SammyContract, generated by
/// the server and copied verbatim): every response decodes through the code
/// Influx reads it with, and every request Influx builds is exactly the one
/// the server recorded. A change on either side fails here before it can
/// break a live connection.
private enum Contract {
    /// The typed origin the server generated the files for.
    static let origin = "https://example.com"
    /// The fixed proof key and state the recorded requests were made with
    /// (the verifier is RFC 7636's appendix B example).
    static let verifier = "dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk"
    static let state = "Contract-State_0123456789.~"

    static func data(_ name: String) throws -> Data {
        let url = try #require(Bundle.module.url(forResource: name, withExtension: nil, subdirectory: "Fixtures/SammyContract"))
        return try Data(contentsOf: url)
    }

    static func object(_ name: String) throws -> [String: Any] {
        try #require(try JSONSerialization.jsonObject(with: data(name)) as? [String: Any])
    }

    /// `name`'s `body` object, as the server sends it.
    static func body(_ name: String) throws -> Data {
        try JSONSerialization.data(withJSONObject: try #require(object(name)["body"]))
    }

    static func strings(_ value: Any?) throws -> [String: String] {
        try #require(value as? [String: String])
    }

    /// Hashing for PKCE where Linux has no CryptoKit.
    static let crypto = OAuthCrypto(
        sha256: { Data(TestSHA256.digest($0)) },
        randomBytes: { Data(repeating: 7, count: $0) },
        newKey: { FakeDPoPKey() },
        restoreKey: { FakeDPoPKey(name: String(decoding: $0, as: UTF8.self)) }
    )

    /// What the server sends with its article list and its article pages.
    static let listHeaders = ["Content-Type": "application/json"]
    static let pageHeaders = ["Content-Type": "application/feed+json; charset=utf-8"]

    /// A Sammy server that answers from the contract files.
    static func server() throws -> FakeHTTPClient {
        let routes: [String: FakeHTTPClient.Response] = [
            "\(origin)/.well-known/oauth-authorization-server": .init(body: try data("oauth-authorization-server.json")),
            "\(origin)/oauth/token": .init(body: try body("token-response.json")),
            "\(origin)/oauth/revoke": .init(),
            "\(origin)/api/v1/feeds": .init(headers: listHeaders, body: try data("feed-list-oauth.json")),
        ]
        return FakeHTTPClient(routes: routes)
    }

    /// The approved sign-in, begun and finished with the fixed proof key
    /// and state against `http`.
    static func signIn(_ http: FakeHTTPClient, credentials: any CredentialStore = InMemoryCredentialStore()) async throws -> (SammySession, [Source]) {
        let sammy = SammySignIn(http: http, crypto: crypto, credentials: credentials)
        let pending = sammy.begin(try await sammy.discover(server: origin), state: state, pkce: PKCE(verifier: verifier, crypto: crypto))
        let address = try #require(object("callback-approved.json")["url"] as? String)
        let callback = try #require(URL(string: address))
        return try await sammy.complete(pending, callback: callback)
    }

    static func form(_ body: Data?) -> [String: String] {
        var components = URLComponents()
        components.percentEncodedQuery = String(decoding: body ?? Data(), as: UTF8.self)
        return Dictionary((components.queryItems ?? []).map { ($0.name, $0.value ?? "") }, uniquingKeysWith: { $1 })
    }
}

@Suite struct SammyContractTests {
    // MARK: The files

    @Test func everyFileMatchesItsHashInTheManifest() throws {
        struct Manifest: Decodable {
            struct File: Decodable { var name: String; var sha256: String }
            var contractVersion: Int
            var files: [File]
        }
        let manifest = try JSONDecoder().decode(Manifest.self, from: Contract.data("manifest.json"))
        #expect(manifest.contractVersion >= 2)
        #expect(manifest.files.count == 15)
        for file in manifest.files {
            #expect(TestSHA256.hex(try Contract.data(file.name)) == file.sha256, "\(file.name)")
        }
        // Every file in the folder is in the manifest: none added by hand.
        let folder = try #require(Bundle.module.url(forResource: "manifest", withExtension: "json", subdirectory: "Fixtures/SammyContract"))
            .deletingLastPathComponent()
        let present = try FileManager.default.contentsOfDirectory(atPath: folder.path).filter { $0.hasSuffix(".json") && $0 != "manifest.json" }
        #expect(Set(present) == Set(manifest.files.map(\.name)))
    }

    @Test func theHashIsSHA256() {
        #expect(TestSHA256.hex(Data("abc".utf8)) == "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad")
        #expect(TestSHA256.hex(Data()) == "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855")
    }

    // MARK: What the server sends

    @Test func theFeedListDecodesWithAndWithoutTheAccountID() throws {
        let issuer = try #require(URL(string: Contract.origin))
        let plain = try SammyFeedList.decode(Contract.data("feed-list.json"))
        #expect(plain.account.id == nil)
        #expect(plain.account.server == Contract.origin)
        let oauth = try SammyFeedList.decode(Contract.data("feed-list-oauth.json"))
        #expect(oauth.account.id == "AbCdEfGhIjKlMnOpQrStUv")
        for list in [plain, oauth] {
            #expect(list.feeds.map(\.title) == ["Movies: first scores", "New TV: first scores"])
            #expect(list.feeds.map(\.key) == ["movies", "tv"])
            #expect(list.feeds[0].lastPostAt == FeedDate.iso8601("2026-10-30T10:07:12Z"))
            #expect(list.feeds[1].lastPostAt == nil)
            let sources = SammyFeedConnector.sources(of: list, accountID: "AbCdEfGhIjKlMnOpQrStUv@example.com", issuer: issuer, colorIndex: 0)
            #expect(sources.map(\.id) == [
                "sammy:AbCdEfGhIjKlMnOpQrStUv@example.com:feed:0193a1b2-0000-7000-8000-00000000f001",
                "sammy:AbCdEfGhIjKlMnOpQrStUv@example.com:feed:0193a1b2-0000-7000-8000-00000000f002",
            ])
            #expect(sources.map(\.url) == list.feeds.map(\.feedURL))
        }
    }

    @Test func aFeedListWithoutTheAccountIDDoesNotSignIn() async throws {
        let http = try Contract.server()
        http.respond { request in
            switch request.url?.path {
            case "/.well-known/oauth-authorization-server": .init(body: try Contract.data("oauth-authorization-server.json"))
            case "/oauth/token": .init(body: try Contract.body("token-response.json"))
            case "/api/v1/feeds": .init(headers: Contract.listHeaders, body: try Contract.data("feed-list.json"))
            default: .init()
            }
        }
        await #expect(throws: SammySignInError.notASammyServer("account id")) { try await Contract.signIn(http) }
        // The token it was given is revoked.
        #expect(http.requests.last?.url?.path == "/oauth/revoke")
    }

    @Test func bothPagesDecodeAndMapToArticles() throws {
        let source = Source(id: "sammy:s@example.com:feed:f1", kind: .sammyFeed, accountID: "s@example.com", title: "Movies", url: nil, colorIndex: 0)
        let now = Date(timeIntervalSince1970: 1_793_000_000)
        let first = try JSONFeed.decode(Contract.data("feed-page-1.json"))
        #expect(first.title == "Movies: first scores")
        #expect(first.nextURL?.hasPrefix("https://example.com/api/v1/feeds/0193a1b2-0000-7000-8000-00000000f001?before=") == true)
        #expect(first.items.count == 2)
        #expect(first.items[0].sammy?.metascore == .init(value: 65, max: 100, band: "favorable"))
        #expect(first.items[0].sammy?.imageSize == .init(width: 352, height: 528))
        #expect(first.items[1].sammy?.metascore?.band == "unfavorable")

        let items = first.items.compactMap { JSONFeedMapper.item(from: $0, feed: first, source: source, fetchedAt: now) }
        #expect(items.map(\.remoteID) == ["urn:uuid:0193a1b2-0000-7000-8000-00000000a003", "urn:uuid:0193a1b2-0000-7000-8000-00000000a002"])
        #expect(items.map(\.mergeKey) == items.map(\.remoteID))
        #expect(items[0].title == "Example Film & \"Friends\" <Three>")
        // The summary, with its score glyph, is what the row shows.
        #expect(items[0].body == "🟢 65 · Out Nov 12, 2026 — Critics find it warm and slight. A synthetic film for the contract.")
        #expect(items[1].body == "🔴 31 · Out Oct 30, 2026")
        #expect(items[0].url == "https://www.example.com/movie/example-film-three/")
        #expect(items[0].authorName == "Movies: first scores")
        #expect(items[0].publishedAt == FeedDate.iso8601("2026-10-30T10:07:12Z"))
        #expect(items.allSatisfy { $0.kind == .article && $0.body.count <= 400 })

        let second = try JSONFeed.decode(Contract.data("feed-page-2.json"))
        #expect(second.nextURL == nil)
        let last = try #require(second.items.first.flatMap { JSONFeedMapper.item(from: $0, feed: second, source: source, fetchedAt: now) })
        // No summary: the plain text is the body.
        #expect(last.body == "Metascore 50 (mixed or average)")
        #expect(last.url == nil)
        #expect(last.mergeKey == "urn:uuid:0193a1b2-0000-7000-8000-00000000a001")
    }

    @Test func theConnectorPagesFromTheFirstPageToTheSecondThroughNextURL() async throws {
        let page1 = try Contract.data("feed-page-1.json")
        let next = try #require(try JSONFeed.decode(page1).nextURL)
        let feed = "https://example.com/api/v1/feeds/0193a1b2-0000-7000-8000-00000000f001"
        let http = FakeHTTPClient(routes: [
            feed: .init(headers: Contract.pageHeaders.merging(["ETag": "W/\"2783f7f47fdabd661f4b857f03499625bca8290b\""]) { $1 }, body: page1),
            next: .init(headers: Contract.pageHeaders, body: try Contract.data("feed-page-2.json")),
            "https://example.com/media/feed-images/AbCdEfGhIjKlMnOpQrStUvWxYz0123456789-_AbCde": .init(body: MediaFixtures.jpeg(width: 352, height: 528)),
        ])
        let (connector, source) = try await contractConnector(http)
        let now = Date(timeIntervalSince1970: 1_793_000_000)
        let request = FetchRequest(direction: .newer, cursor: nil, notBefore: .distantPast, now: now)
        let first = try await connector.fetch(request, from: source)
        #expect(first.items.count == 2)
        #expect(first.items[0].media.first?.url == "https://example.com/media/feed-images/AbCdEfGhIjKlMnOpQrStUvWxYz0123456789-_AbCde")
        #expect(first.older == Cursor(rawValue: next))
        let older = try await connector.fetch(FetchRequest(direction: .older, cursor: first.older, notBefore: .distantPast, now: now), from: source)
        #expect(older.items.map(\.remoteID) == ["urn:uuid:0193a1b2-0000-7000-8000-00000000a001"])
        #expect(older.older == nil)
        // Feed requests carry the token; the image request doesn't.
        let feedRequests = http.requests.filter { $0.url?.path.hasPrefix("/api/") == true }
        #expect(feedRequests.count == 2)
        #expect(feedRequests.allSatisfy { $0.value(forHTTPHeaderField: "Authorization") == "Bearer sao_contract-example-access-token" })
        #expect(http.requests.filter { $0.url?.path.hasPrefix("/media/") == true }.allSatisfy { $0.value(forHTTPHeaderField: "Authorization") == nil })
    }

    @Test func the304KeepsTheCursorAndItsRequestCarriesTheRecordedValidator() async throws {
        let recorded = try Contract.object("feed-not-modified.json")
        let requestHeaders = try Contract.strings((recorded["request"] as? [String: Any])?["headers"])
        let response = try #require(recorded["response"] as? [String: Any])
        let responseHeaders = try Contract.strings(response["headers"])
        let status = try #require(response["status"] as? Int)
        let etag = try #require(responseHeaders["ETag"])
        let http = FakeHTTPClient { request in
            request.value(forHTTPHeaderField: "If-None-Match") == requestHeaders["If-None-Match"]
                ? .init(status: status, headers: responseHeaders) : .init(status: 500)
        }
        let (connector, source) = try await contractConnector(http)
        let cursor = SammyFeedConnector.Validators(etag: etag, accept: SammyNegotiation.either, format: .article).cursor
        let page = try await connector.fetch(FetchRequest(direction: .newer, cursor: cursor, notBefore: .distantPast, now: Date()), from: source)
        #expect(status == 304)
        #expect(page.items.isEmpty)
        #expect(page.newer == cursor)
        #expect(http.requests.count == 1)
        #expect(http.requests.first?.value(forHTTPHeaderField: "If-None-Match") == requestHeaders["If-None-Match"])
    }

    @Test func theTokenResponsesReadAsSammyOAuthReadsThem() throws {
        let url = try #require(URL(string: "\(Contract.origin)/oauth/token"))
        let granted = try Contract.object("token-response.json")
        let okStatus = try #require(granted["status"] as? Int)
        let ok = try #require(HTTPURLResponse(url: url, statusCode: okStatus, httpVersion: nil, headerFields: nil))
        let tokens = try SammyOAuth.tokens(from: Contract.body("token-response.json"), ok, now: Date())
        #expect(tokens == .init(accessToken: "sao_contract-example-access-token", scope: "feeds:read"))

        let refused = try Contract.object("token-error-invalid-grant.json")
        let badStatus = try #require(refused["status"] as? Int)
        let bad = try #require(HTTPURLResponse(url: url, statusCode: badStatus, httpVersion: nil, headerFields: nil))
        #expect(throws: ConnectorError.unauthorized) { try SammyOAuth.tokens(from: Contract.body("token-error-invalid-grant.json"), bad, now: Date()) }
    }

    @Test func theMetadataIsASammyServerForTheTypedOrigin() async throws {
        let http = try Contract.server()
        let oauth = try await SammySignIn(http: http, crypto: Contract.crypto, credentials: InMemoryCredentialStore()).discover(server: Contract.origin)
        #expect(oauth.issuer == Contract.origin)
        #expect(oauth.server.authorizationEndpoint.absoluteString == "https://example.com/oauth/authorize")
        #expect(oauth.server.tokenEndpoint.absoluteString == "https://example.com/oauth/token")
        #expect(oauth.server.revocationEndpoint?.absoluteString == "https://example.com/oauth/revoke")
        #expect(oauth.requiresIssuer)

        // The resource metadata describes the server's MCP endpoint, which
        // Influx never reads; it names the same issuer and takes the token
        // in a header, as the feed API does.
        let resource = try Contract.object("oauth-protected-resource.json")
        #expect(resource["authorization_servers"] as? [String] == [Contract.origin])
        #expect((resource["bearer_methods_supported"] as? [String])?.contains("header") == true)
    }

    // MARK: What Influx sends

    @Test func influxIsTheRegisteredClient() throws {
        let clients = try #require(try Contract.object("client-registration.json")["clients"] as? [[String: Any]])
        let influx = try #require(clients.first { $0["client_id"] as? String == SammyOAuth.clientID })
        #expect((influx["redirect_uris"] as? [String])?.contains(SammyOAuth.redirect) == true)
        #expect((influx["scopes"] as? [String])?.contains(SammyOAuth.scope) == true)
        #expect(influx["token_endpoint_auth_method"] as? String == "none")
        #expect(influx["grant_types"] as? [String] == ["authorization_code"])
        #expect(influx["response_types"] as? [String] == ["code"])
        #expect(influx["code_challenge_methods"] as? [String] == ["S256"])
    }

    @Test func beginBuildsExactlyTheRecordedAuthorizeRequest() async throws {
        let recorded = try Contract.object("authorize-request.json")
        let http = try Contract.server()
        let sammy = SammySignIn(http: http, crypto: Contract.crypto, credentials: InMemoryCredentialStore())
        let pending = sammy.begin(try await sammy.discover(server: Contract.origin), state: Contract.state, pkce: PKCE(verifier: Contract.verifier, crypto: Contract.crypto))
        let url = pending.authorizationURL
        var endpoint = try #require(URLComponents(url: url, resolvingAgainstBaseURL: false))
        let items = endpoint.queryItems ?? []
        endpoint.query = nil
        #expect(recorded["method"] as? String == "GET")
        #expect(endpoint.url?.absoluteString == recorded["endpoint"] as? String)
        // Exactly the recorded parameters: none missing, none added, none twice.
        #expect(items.count == Set(items.map(\.name)).count)
        #expect(Dictionary(items.map { ($0.name, $0.value ?? "") }, uniquingKeysWith: { $1 }) == (try Contract.strings(recorded["query"])))
    }

    @Test func thePKCEChallengeIsS256OfTheVerifier() throws {
        let recorded = try Contract.strings(Contract.object("authorize-request.json")["query"])
        #expect(PKCE(verifier: Contract.verifier, crypto: Contract.crypto).challenge == recorded["code_challenge"])
        #if canImport(CryptoKit)
        #expect(PKCE(verifier: Contract.verifier, crypto: .system).challenge == recorded["code_challenge"])
        #endif
    }

    @Test func theCodeIsExchangedWithExactlyTheRecordedTokenRequest() async throws {
        let recorded = try Contract.object("token-request.json")
        let http = try Contract.server()
        let (session, sources) = try await Contract.signIn(http)
        let sent = try #require(http.requests.first { $0.url?.path == "/oauth/token" })
        #expect(sent.httpMethod == recorded["method"] as? String)
        #expect(sent.url?.absoluteString == recorded["endpoint"] as? String)
        #expect(sent.value(forHTTPHeaderField: "Content-Type") == recorded["contentType"] as? String)
        #expect(String(decoding: sent.httpBody ?? Data(), as: UTF8.self) == recorded["body"] as? String)
        #expect(Contract.form(sent.httpBody) == (try Contract.strings(recorded["form"])))
        // The approved callback signed the account in, named by its subject.
        #expect(session.accountID == "AbCdEfGhIjKlMnOpQrStUv@example.com")
        #expect(session.accessToken == "sao_contract-example-access-token")
        #expect(sources.count == 2)
    }

    @Test func signingOutRevokesWithExactlyTheRecordedRevokeRequest() async throws {
        let recorded = try Contract.object("revoke-request.json")
        let http = try Contract.server()
        let credentials = InMemoryCredentialStore()
        let (session, _) = try await Contract.signIn(http, credentials: credentials)
        await SammyAccount(session: session, http: http, credentials: credentials).signOut()
        let revokes = http.requests.filter { $0.url?.path == "/oauth/revoke" }
        let sent = try #require(revokes.first)
        #expect(revokes.count == 1)
        #expect(sent.httpMethod == recorded["method"] as? String)
        #expect(sent.url?.absoluteString == recorded["endpoint"] as? String)
        #expect(sent.value(forHTTPHeaderField: "Content-Type") == recorded["contentType"] as? String)
        #expect(String(decoding: sent.httpBody ?? Data(), as: UTF8.self) == recorded["body"] as? String)
        #expect(Contract.form(sent.httpBody) == (try Contract.strings(recorded["form"])))
    }

    @Test func theCallbacksAreAcceptedAndDeniedAsRecorded() async throws {
        let http = try Contract.server()
        let sammy = SammySignIn(http: http, crypto: Contract.crypto, credentials: InMemoryCredentialStore())
        let oauth = try await sammy.discover(server: Contract.origin)
        let pending = sammy.begin(oauth, state: Contract.state, pkce: PKCE(verifier: Contract.verifier, crypto: Contract.crypto))

        let approved = try Contract.object("callback-approved.json")
        let approvedAddress = try #require(approved["url"] as? String)
        let approvedURL = try #require(URL(string: approvedAddress))
        let approvedParams = try Contract.strings(approved["params"])
        #expect(try oauth.code(fromCallback: approvedURL, expectedState: Contract.state) == approvedParams["code"])
        #expect(approvedParams["iss"] == oauth.issuer)
        #expect(approvedParams["state"] == Contract.state)

        let denied = try Contract.object("callback-denied.json")
        let deniedAddress = try #require(denied["url"] as? String)
        let deniedURL = try #require(URL(string: deniedAddress))
        #expect(try Contract.strings(denied["params"])["error"] == "access_denied")
        await #expect(throws: SammySignInError.callback(.denied("access_denied"))) { try await sammy.complete(pending, callback: deniedURL) }
        #expect(!http.requests.contains { $0.url?.path == "/oauth/token" })
    }

    /// A connector for the contract account, signed in from the files.
    private func contractConnector(_ http: FakeHTTPClient) async throws -> (SammyFeedConnector, Source) {
        let session = SammySession(
            issuer: try #require(URL(string: Contract.origin)), revocationEndpoint: URL(string: "\(Contract.origin)/oauth/revoke"),
            accessToken: "sao_contract-example-access-token", subject: "AbCdEfGhIjKlMnOpQrStUv"
        )
        let credentials = InMemoryCredentialStore()
        try credentials.save(session, for: session.accountID)
        let account = SammyAccount(session: session, http: http, credentials: credentials)
        let list = try SammyFeedList.decode(Contract.data("feed-list-oauth.json"))
        let source = try #require(SammyFeedConnector.sources(of: list, accountID: session.accountID, issuer: session.issuer, colorIndex: 0).first)
        return (SammyFeedConnector(account: account, http: http, resolver: .testing(http)), source)
    }
}
